contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seedDrugs) public {
        c.seedMarket(seedDrugs); if (__ESBMC_reverted()) return;
        require(c.initialized());
        require(c.marketDrugs() == seedDrugs);
        c.getFreeKilo(); if (__ESBMC_reverted()) return;
        uint256 kilos = c.getMyKilo(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.getFreeKilo(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && kilos == c.STARTING_KILOS());
    }
    receive() external payable {}
}

