// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedDrugs) internal {
        try c.seedMarket(seedDrugs) {} catch { return; }
        vm.assume(c.initialized());
        seedDrugs = c.marketDrugs();
        try c.getFreeKilo() {} catch { return; }
        uint256 kilos;
        try c.getMyKilo() returns (uint256 __r) { kilos = __r; } catch { return; }
        bool reverted;
        try c.getFreeKilo() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && kilos == c.STARTING_KILOS());
    }

    function testFuzz_run(uint256 seedDrugs) public {
        _run(seedDrugs);
    }

    receive() external payable {}
}
